macro_rules! deps {
    () => {
        Graph!();
        AlgoResult!();
        Directed!();
        Measure!();
        EdgeRef!();
        MinScored!();
    };
}

macro_rules! with_dynamic_goal {
    () => {
        deps!();
        # [doc = " Dijkstra's shortest path algorithm with a dynamic goal."] # [doc = ""] # [doc = " This algorithm is identical to [`dijkstra`],"] # [doc = " but allows matching multiple goal nodes, whichever is reached first."] # [doc = " A node is considered a goal if `goal_fn` returns `true` for it."] # [doc = ""] # [doc = " See the [`dijkstra`] function for more details."] # [doc = ""] # [doc = " # Example"] # [doc = " ```rust"] # [doc = " use petgraph::Graph;"] # [doc = " use petgraph::algo::dijkstra;"] # [doc = " use petgraph::prelude::*;"] # [doc = " use hashbrown::HashMap;"] # [doc = ""] # [doc = " let mut graph: Graph<(), (), Directed> = Graph::new();"] # [doc = " let a = graph.add_node(()); // node with no weight"] # [doc = " let b = graph.add_node(());"] # [doc = " let c = graph.add_node(());"] # [doc = " let d = graph.add_node(());"] # [doc = " let e = graph.add_node(());"] # [doc = " let f = graph.add_node(());"] # [doc = " let g = graph.add_node(());"] # [doc = " let h = graph.add_node(());"] # [doc = " // z will be in another connected component"] # [doc = " let z = graph.add_node(());"] # [doc = ""] # [doc = " graph.extend_with_edges(&["] # [doc = "     (a, b),"] # [doc = "     (b, c),"] # [doc = "     (c, d),"] # [doc = "     (d, a),"] # [doc = "     (e, f),"] # [doc = "     (b, e),"] # [doc = "     (f, g),"] # [doc = "     (g, h),"] # [doc = "     (h, e),"] # [doc = " ]);"] # [doc = " // a ----> b ----> e ----> f"] # [doc = " // ^       |       ^       |"] # [doc = " // |       v       |       v"] # [doc = " // d <---- c       h <---- g"] # [doc = ""] # [doc = " let expected_res: HashMap<NodeIndex, usize> = ["] # [doc = "     (b, 0),"] # [doc = "     (c, 1),"] # [doc = "     (d, 2),"] # [doc = "     (e, 1),"] # [doc = "     (f, 2),"] # [doc = " ].iter().cloned().collect();"] # [doc = " let res = dijkstra::with_dynamic_goal(&graph, b, |&node| node == d || node == f, |_| 1);"] # [doc = " assert_eq!(res.scores, expected_res);"] # [doc = " assert!(res.goal_node == Some(d) || res.goal_node == Some(f));"] # [doc = " ```"] pub fn with_dynamic_goal < G , GoalFn , CostFn , K > (graph : G , start : G :: NodeId , mut goal_fn : GoalFn , mut edge_cost : CostFn ,) -> AlgoResult < G :: NodeId , K > where G : IntoEdges + Visitable , G :: NodeId : Eq + Hash , GoalFn : FnMut (& G :: NodeId) -> bool , CostFn : FnMut (G :: EdgeRef) -> K , K : Measure + Copy , { let mut visited = graph . visit_map () ; let mut scores = HashMap :: new () ; let mut visit_next = BinaryHeap :: new () ; let zero_score = K :: default () ; scores . insert (start , zero_score) ; visit_next . push (MinScored (zero_score , start)) ; let mut goal_node = None ; while let Some (MinScored (node_score , node)) = visit_next . pop () { if visited . is_visited (& node) { continue ; } if goal_fn (& node) { goal_node = Some (node) ; break ; } for edge in graph . edges (node) { let next = edge . target () ; if visited . is_visited (& next) { continue ; } let next_score = node_score + edge_cost (edge) ; match scores . entry (next) { Occupied (ent) => { if next_score < * ent . get () { * ent . into_mut () = next_score ; visit_next . push (MinScored (next_score , next)) ; } } Vacant (ent) => { ent . insert (next_score) ; visit_next . push (MinScored (next_score , next)) ; } } } visited . visit (node) ; } AlgoResult { scores , goal_node } }
    };
}

with_dynamic_goal!()